  if(theme==1&&(categoryIndex==0||categoryIndex==1))display.add(tr("只计已确认战后奖励；同次同名候选最多出现一次；已知自动化的选择不计入。","Confirmed combat rewards only; duplicate offers count once per choice; known automation is left out."));
