 String unitName(String unit){switch(unit){case "run_act":return tr("局·幕","run-acts");case "combat":return tr("场","fights");case "choice_set":return tr("屏","screens");case "choice":return tr("次","offers");case "event":return tr("次","events");default:return tr("局","runs");}}
 String label(String key){if(key.startsWith("related:"))return label(key.substring(8))+tr(" · 所选对局胜率（相关）"," · Selected-run win rate (association)");if(key.equals("outcome:victory"))return tr("胜利（杀心另计）","Victories (Heart counted separately)");if(key.equals("outcome:abandon"))return tr("放弃","Abandoned");if(key.equals("outcome:unknown"))return tr("结局未知","Result unknown");
  if(key.startsWith("death_count:")||key.startsWith("death:")||key.startsWith("damage:")||key.startsWith("encounter_potions:"))return encounter(key.substring(key.indexOf(':')+1));if(key.equals("death_count_unknown"))return tr("死因未知","Cause of death unknown");
  if(key.startsWith("event:")){String[] pair=key.substring(6).split(" / ",2);return com.megacrit.cardcrawl.helpers.EventHelper.getEventName(pair[0])+(pair.length>1?" · "+pair[1]:"");}if(key.startsWith("neow:"))return neow(key.substring(5));
  if(key.equals("win"))return tr("胜率","Win rate");if(key.equals("time"))return tr("平均游戏时间","Mean playtime");if(key.equals("deck_size"))return tr("平均终局牌组大小","Mean final deck size");
  if(key.equals("gold_gained"))return tr("平均累计获得金币","Mean gold gained");if(key.equals("gold_gained:exact"))return tr("  其中精确","  of which exact");if(key.equals("gold_gained:estimated"))return tr("  其中估算","  of which estimated");
  if(key.equals("reward_source:unknown"))return tr("操作来源未知的选牌占比","Share of picks with unknown action source");if(key.equals("reward_automation_excluded"))return tr("已知自动化选择（不计入）","Known automation choices (left out)");
  if(key.startsWith("outcome:"))return host.outcome(key.substring(8));if(key.startsWith("act:"))return tr("第 ","Act ")+key.substring(4)+tr(" 幕通过率"," completion");if(key.startsWith("act_hp_loss:"))return tr("第 ","Act ")+key.substring(12)+tr(" 幕总战损（每局）"," total HP loss per run");String[] parts=key.split(":",3);String tail=parts.length==3?parts[2]:parts.length==2?parts[1]:key;
  if(key.startsWith("hp_loss"))return tr("幕 ","Act ")+parts[1]+" · "+encounter(tail)+(key.startsWith("hp_loss_heal:")?tr(" · 有回复"," · healed"):key.startsWith("hp_loss_noheal:")?tr(" · 无回复"," · not healed"):"");
  if(key.startsWith("pick:"))return tr("幕 ","Act ")+parts[1]+" · "+HistoryScreen.cardName(tail);if(key.startsWith("skip:")||key.startsWith("bowl:"))return tr("幕 ","Act ")+parts[1]+" · "+(key.startsWith("skip:")?tr("跳过","Skip"):tr("歌唱碗","Bowl"));if(key.startsWith("holding:"))return HistoryScreen.cardName(tail);if(key.startsWith("boss:"))return tr("幕 ","Act ")+parts[1]+" · "+(tail.equals("SKIP")?tr("跳过","Skip"):HistoryScreen.relicName(tail));
  if(key.startsWith("upgrade:")||key.startsWith("remove:"))return (key.startsWith("upgrade:")?tr("升级","Upgrade"):tr("删除","Remove"))+" · "+(parts[1].equals("observed")?tr("观察到（不归因）","Observed, no attribution"):parts[1].equals("shop")?tr("商店","Shop"):parts[1].equals("campfire")?tr("火堆","Campfire"):tr("事件","Event"))+" · "+HistoryScreen.cardName(tail);if(key.equals("potions"))return tr("已记录药水使用","Recorded potion uses");if(key.startsWith("purchase:"))return tr("购买 · ","Bought · ")+itemName(tail);if(key.startsWith("campfire:")){switch(tail){case "SMITH":return tr("火堆升级","Campfire smith");case "REST":return tr("火堆休息","Campfire rest");case "RECALL":return tr("召回钥匙","Recall key");default:return tr("火堆 · ","Campfire · ")+tail;}}return tail;
 }
 /** metrics.md 1.2, 1.5, 3.3: hidden win rates read "—", missing reads "not recorded", below the minimum reads "too few samples"; numbers otherwise come with their denominators. */
 void line(Metric m){if(m==null){display.add(tr("该项未记录","Not recorded"));return;}String value;
  switch(m.status){case "hidden_by_result_filter":value="—";break;case "missing":value=tr("未记录","Not recorded");break;case "below_min_sample":value=tr("样本不足","Too few samples")+" ("+quantity(m.samples)+")";break;
   default:value=m.kind.equals(Metric.RATE)?String.format(Locale.ROOT,"%.1f%%  (%s / %s)",m.value()*100,quantity(m.numerator),quantity(m.denominator)):m.kind.equals(Metric.COUNT)?quantity(m.numerator):String.format(Locale.ROOT,"%.1f %s  (%s / %s)",m.value(),m.measure.equals("seconds")?tr("秒","s"):m.measure.equals("cards")?tr("张","cards"):m.measure.equals("hp")?tr("生命","HP"):m.measure.equals("potions")?tr("瓶","potions"):m.measure.equals("gold")?tr("金币","gold"):m.measure,quantity(m.numerator),quantity(m.denominator));}
  value+=(m.estimated>0&&m.shown()?tr(" · 含估算 "," · estimated ")+m.estimated:"")+(m.excluded>0&&m.shown()?tr(" · 未知不计 "," · Unknown excluded ")+m.excluded:"");metricRows.put(display.size(),new HistoryScreen.Row(label(m.key),value,HistoryScreen.Tone.NORMAL,HistoryScreen.Tone.CHANGED,true));display.add(label(m.key)+"   "+value);}
 String itemName(String id){if(com.megacrit.cardcrawl.helpers.CardLibrary.getCard(id)!=null)return HistoryScreen.cardName(id);try{String name=HistoryScreen.relicName(id);if(!name.equals(id))return name;}catch(Exception ignored){}try{return CardCrawlGame.languagePack.getPotionString(id).NAME;}catch(Exception ignored){return id;}}
 String encounter(String id){try{return MonsterHelper.getEncounterName(id);}catch(Exception e){return id;}}String neow(String id){String[][] names={{"RANDOM_COLORLESS_2","稀有无色牌","Rare colorless card"},{"RANDOM_COLORLESS","无色牌","Colorless card"},{"THREE_CARDS","三张卡中选一张","Choose one of three cards"},{"ONE_RANDOM_RARE_CARD","随机稀有牌","Random rare card"},{"REMOVE_TWO","删两张牌","Remove two cards"},{"REMOVE_CARD","删牌","Remove a card"},{"UPGRADE_CARD","升级牌","Upgrade a card"},{"TRANSFORM_TWO_CARDS","变两张牌","Transform two cards"},{"TRANSFORM_CARD","变牌","Transform a card"},{"THREE_SMALL_POTIONS","三瓶药水","Three potions"},{"RANDOM_COMMON_RELIC","普通遗物","Common relic"},{"TEN_PERCENT_HP_BONUS","最大生命 +10%","Max HP +10%"},{"HUNDRED_GOLD","100 金币","100 gold"},{"THREE_ENEMY_KILL","前三场敌人 1 HP","First three encounters: 1 HP"},{"ONE_RARE_RELIC","稀有遗物","Rare relic"},{"THREE_RARE_CARDS","三张稀有牌选一","Choose one rare card"},{"TWO_FIFTY_GOLD","250 金币","250 gold"},{"TWENTY_PERCENT_HP_BONUS","最大生命 +20%","Max HP +20%"},{"BOSS_RELIC","替换初始遗物","Swap starting relic"},{"NONE","无代价","No cost"},{"TEN_PERCENT_HP_LOSS","损失最大生命","Lose max HP"},{"NO_GOLD","失去金币","Lose gold"},{"CURSE","获得诅咒","Receive curse"},{"PERCENT_DAMAGE","受到伤害","Take damage"}};for(String[] name:names)id=id.replace(name[0],tr(name[1],name[2]));return id;}String quantity(double n){return n==(long)n?String.valueOf((long)n):String.format(Locale.ROOT,"%.1f",n);}
 void dismissMenus(){for(DropdownMenu d:filters)d.isOpen=false;for(DropdownMenu d:Arrays.asList(category,fromMonth,toMonth,chartAct))if(d!=null)d.isOpen=false;}
 boolean openDropdown(){for(DropdownMenu d:filters)if(d.isOpen)return true;return category.isOpen||fromMonth.isOpen||toMonth.isOpen||chartAct!=null&&chartAct.isOpen;}
 List<DropdownMenu> visibleMenus(){List<DropdownMenu> out=new ArrayList<>();for(int i:new int[]{0,1,2})out.add(filters[i]);out.add(theme==3?chartAct:category);if(selected[2]==1){out.add(fromMonth);out.add(toMonth);}if(advanced)for(int i:new int[]{3,4,5,6,7,8})out.add(filters[i]);return out;}
 void update(){load();if(task!=null&&task.isDone()){try{index=task.get();Set<String> availableMonths=new TreeSet<>(Comparator.reverseOrder());SimpleDateFormat format=new SimpleDateFormat("yyyy-MM",Locale.ROOT);for(Run r:index.runs)if(r.time.or(0L)>0)availableMonths.add(format.format(new Date(r.time.value)));months=new ArrayList<>(availableMonths);setMonths();status="";rebuild();}catch(Exception e){status=tr("战绩读取失败：","Read failed: ")+e.getClass().getSimpleName();}task=null;}
  host.cancel.update();if(host.cancel.hb.clicked||InputHelper.pressedEscape){host.cancel.hb.clicked=false;host.close();return;}
  for(DropdownMenu d:visibleMenus())d.update();if(openDropdown())return;
  List<Hitbox> controls=new ArrayList<>(Arrays.asList(host.latestTab,host.historyTab,host.home));controls.addAll(Arrays.asList(themes));for(DropdownMenu d:visibleMenus())controls.add(d.getHitbox());controls.addAll(Arrays.asList(clearButton,refreshButton,advancedButton,host.prev,host.next,host.cancel.hb));if(theme==3)controls.add(exportButton);host.controller(controls);
  for(int i=0;i<themes.length;i++)if(host.click(themes[i])){theme=i;resetCategory();rebuild();}
  if(host.click(advancedButton)){advanced=!advanced;dismissMenus();offset=0;rebuild();}
  if(host.click(clearButton)){Arrays.fill(selected,0);for(DropdownMenu d:filters)d.setSelectedIndex(0);categoryIndex=0;category.setSelectedIndex(0);fromIndex=toIndex=0;fromMonth.setSelectedIndex(0);toMonth.setSelectedIndex(0);offset=0;rebuild();}
  if(host.click(refreshButton)){if(theme==3&&chart.lastExport!=null){try{java.awt.Desktop.getDesktop().open(chart.lastExport.toFile());}catch(Exception e){chart.message=tr("无法打开文件夹：","Cannot open folder: ")+chart.lastExport;}}else{requested=false;host.refresh();}}
  if(theme==3&&host.click(exportButton)){if(chart.rows.isEmpty())chart.message=tr("当前筛选没有可导出的抓率记录。","No pick-rate records to export.");else chart.exportRequested=true;}
  int move=InputHelper.scrolledDown?1:InputHelper.scrolledUp?-1:0;if(host.click(host.prev))move-=3;if(host.click(host.next))move+=3;
  if(theme==3)chart.scroll(move);else offset=Math.max(0,Math.min(Math.max(0,displayRows.size()-visible()),offset+move*3));
 }
